package com.ailab.system.report.provider;
import com.ailab.system.report.config.ReportConfigCatalog; import com.ailab.system.report.config.ReportSectionConfig; import com.ailab.system.report.model.ReportQueryCriteria; import com.ailab.system.report.model.ReportSectionData; import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class GoalProgressProvider extends AbstractLabDataSourceProvider {
 public GoalProgressProvider(){super(ReportConfigCatalog.GOAL_PROGRESS, set("period","bizLine","owner","ownerId","goalLevel","progressRate","title"));}
 protected ReportSectionData loadValidated(ReportQueryCriteria c, ReportSectionConfig s){List<Map<String,Object>> rows=copyRows(mapper().selectGoalProgress(c)); Map<String,Object> x=summaryCount(rows); BigDecimal total=BigDecimal.ZERO; for(Map<String,Object> r:rows)total=total.add(number(r.get("progressRate")));x.put("averageProgressRate",rows.isEmpty()?BigDecimal.ZERO:total.divide(BigDecimal.valueOf(rows.size()),2,java.math.RoundingMode.HALF_UP));return section(c,s,rows,x);} private static Set<String> set(String...v){return new LinkedHashSet<String>(Arrays.asList(v));}}
